    'birthPreview.hourUnknown': "Time unknown",
    'birthPreview.whatTitle': "What is saju?",
    'birthPreview.whatBody': "Saju (사주, \"four pillars\") is an old East Asian way of reading a life from the moment it began. Your birth year, month, day and hour each become a pillar of two characters: a heavenly stem on top and an earthly branch below. That makes eight characters in all, which is why it is also called the \"eight characters\".\n\nEvery character carries one of five elements: Wood, Fire, Earth, Metal or Water. The top character of the Day pillar (highlighted) stands for you: your day master. How the other seven support, balance or push against it describes your nature, your relationships and work, and the rhythm of the years ahead.\n\nThink of it less like a horoscope that predicts and more like a map of your tendencies. Your counselor reads this chart when you talk.",
