    'birthPreview.whatBody': "四柱推命（サジュ）は、生まれた瞬間から人生を読み解く東洋の古い占術です。生まれた年・月・日・時がそれぞれ一本の柱になり、上に天の文字（天干）、下に地の文字（地支）があるので全部で八文字。だから「四柱八字」とも呼ばれます。\n\n一つひとつの文字が木・火・土・金・水の五行のどれかを持っています。日柱の上の文字（日干）があなた自身。ほかの七文字がそれをどう助け、どう抑えるかで、性格や人間関係、仕事、これからの時期の流れが見えてきます。カウンセラーはこの命式をもとにお話しします。",
