    'birthPreview.whatBody': "八字（四柱）是東亞古老的命理方法，從一個人出生的那一刻來解讀人生。出生的年、月、日、時各成一柱，每柱上為天干、下為地支，共八個字，所以叫「生辰八字」。\n\n每個字都帶著木、火、土、金、水五行之一。日柱的天干（日主）代表你自己，其餘七個字如何生扶或剋制它，就能看出性格、人際、事業，以及未來幾年的運勢節奏。顧問會根據這張命盤與你交談。",
